DROP TABLE IF EXISTS `ctab6`;
CREATE TABLE `ctab6` (
  `ctab6_id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(12) NOT NULL,
  `name` varchar(255) NOT NULL,
  `level` int(2) NOT NULL DEFAULT '0',
  PRIMARY KEY (`ctab6_id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=MyISAM AUTO_INCREMENT=767 DEFAULT CHARSET=utf8;


DROP TABLE IF EXISTS `ctab9`;
CREATE TABLE `ctab9` (
  `ctab9_id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(12) NOT NULL,
  `name` varchar(255) NOT NULL,
  `order_code` varchar(12) NOT NULL DEFAULT '',
  `accounts` varchar(255) NOT NULL DEFAULT '',
  `level` int(2) NOT NULL DEFAULT '0',
  `list_after` varchar(12) NOT NULL DEFAULT '',
  PRIMARY KEY (`ctab9_id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=MyISAM AUTO_INCREMENT=76 DEFAULT CHARSET=utf8;


